package com.thearkane.boomsepicsounds.trade;

import com.thearkane.boomsepicsounds.BoomsEpicSoundsConfig;

import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.widgets.Widget;


@Slf4j
public class TradeManager
{
    private static final int TRADE_MAIN_GROUP_ID = 335;
    private static final int TRADE_CONFIRM_GROUP_ID = 334;

    private final BoomsEpicSoundsConfig config;
    private final Client client;

    private boolean wasConfirmScreenOpen;

    @Inject
    public TradeManager(BoomsEpicSoundsConfig config, Client client)
    {
        this.config = config;
        this.client = client;
    }

    /**
     * Call once per game tick. Returns true on the tick a trade is
     * detected as successfully completed.
     */
    public boolean check()
    {
        if (!config.tradeAcceptedSoundNotification())
        {
            wasConfirmScreenOpen = false;
            return false;
        }

        boolean confirmOpen = isGroupOpen(TRADE_CONFIRM_GROUP_ID);
        boolean mainOpen = isGroupOpen(TRADE_MAIN_GROUP_ID);

        boolean tradeAccepted = wasConfirmScreenOpen && !confirmOpen && !mainOpen;

        wasConfirmScreenOpen = confirmOpen;

        return tradeAccepted;
    }

    private boolean isGroupOpen(int groupId)
    {
        Widget widget = client.getWidget(groupId, 0);
        return widget != null && !widget.isHidden();
    }
}

package com.thearkane.boomsepicsounds;


import lombok.Getter;

/**
 * A single place that pairs a sound category with its custom-sound folder
 * name, its bundled fallback sound(s), and its priority.
 *
 * Priority determines which sound wins when multiple events fire on the
 * same game tick (e.g. a quest completes on the same tick you level up).
 * Lower number = higher priority = plays first / wins ties.
 */

@Getter
public enum SoundEvent
{
    DEATH(1, "Death", "/death.wav", "/ohno.wav"),
    PLAYER_KILL(2, "PlayerKill", "/sitdown.wav", "/sitdown1.wav"),
    QUEST_COMPLETED(3, "QuestCompleted", "/finallyquestcomplete.wav", "/ohmyyoufinishedanotherquest.wav"),
    COLLECTION_LOG(4, "CollectionLog", "/thehit.wav"),
    LEVEL_UP(5, "LevelUp", "/goodjobbuddyhopeyourhavingfun.wav", "/levelup.wav", "/levelup1.wav"),
    LOOT(6, "Loot", "/thehit.wav"),
    PRAYER(7, "Prayer", "/prayer.wav", "/prayer1.wav"),
    REPORT(8, "Report", "/wellhesgunnagetbanned.wav", "/wellyourgunnagetbanned.wav"),
    LIVESTREAM(9, "Livestream", "/livestream.wav"),
    TRADE_ACCEPTED(10, "TradeAccepted", "/tradeaccepted.wav");

    private final int priority;
    private final String folderName;
    private final String[] fallbackSounds;

    SoundEvent(int priority, String folderName, String... fallbackSounds)
    {
        this.priority = priority;
        this.folderName = folderName;
        this.fallbackSounds = fallbackSounds;
    }

}

package com.thearkane.boomsepicsounds;

import com.thearkane.boomsepicsounds.livestream.LivestreamManager;
import com.thearkane.boomsepicsounds.trade.TradeManager;

import com.google.inject.Provides;
import java.util.Arrays;
import java.util.Comparator;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.PriorityQueue;
import java.util.Queue;
import java.util.Set;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Actor;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.Skill;
import net.runelite.api.events.ActorDeath;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.StatChanged;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemStack;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.plugins.loottracker.LootReceived;
import net.runelite.client.util.Text;
import net.runelite.http.api.item.ItemPrice;

@Slf4j
@PluginDescriptor(
        name = "Booms Epic Sounds",
        description = "Custom sound notifications for RuneLite events",
        tags = {"sounds", "pvm", "pvp", "fun"}
)
public class BoomsEpicSoundsPlugin extends Plugin
{
    private static final String STREAMER_MESSAGE =
            "BoomEpicKill is live daily from 11AM ET";

    /*
     * Maximum time allowed between ActorDeath and the matching
     * "You have defeated..." game message.
     *
     * Five ticks is approximately three seconds.
     */
    private static final int PLAYER_KILL_CONFIRMATION_TICKS = 5;

    /*
     * Player kills and abuse reports are handled separately.
     */
    private final List<ChatTrigger> chatTriggers = List.of(
            new ChatTrigger(
                    SoundEvent.PRAYER,
                    BoomsEpicSoundsConfig::prayerMessage,
                    "you have run out of prayer points",
                    "your prayer has been drained"
            ),
            new ChatTrigger(
                    SoundEvent.QUEST_COMPLETED,
                    BoomsEpicSoundsConfig::questCompletions,
                    "quest complete",
                    "congratulations, quest complete"
            ),
            new ChatTrigger(
                    SoundEvent.COLLECTION_LOG,
                    BoomsEpicSoundsConfig::collectionLog,
                    "new collection log item",
                    "collection log"
            )
    );

    @Inject
    private Client client;

    @Inject
    private BoomsEpicSoundsConfig config;

    @Inject
    private ItemManager itemManager;

    @Inject
    private ChatMessageManager chatMessageManager;

    @Inject
    private SoundManager soundManager;

    @Inject
    private LivestreamManager livestreamManager;

    @Inject
    private TradeManager tradeManager;

    private final Set<Integer> trackedItemIds = new HashSet<>();
    private final int[] lastLevels = new int[Skill.values().length];

    private final Queue<SoundEvent> pendingSounds =
            new PriorityQueue<>(
                    Comparator.comparingInt(SoundEvent::getPriority)
            );

    private boolean wasDead;
    private boolean initialized;
    private boolean pendingReload = true;
    private boolean streamerMessageShown;
    private boolean pendingLevelInit;

    /*
     * Temporary PvP kill candidate recorded by ActorDeath.
     */
    private String recentlyDefeatedPlayerName;
    private int recentlyDefeatedPlayerTick = -1;

    @Provides
    BoomsEpicSoundsConfig provideConfig(ConfigManager configManager)
    {
        return configManager.getConfig(BoomsEpicSoundsConfig.class);
    }

    @Override
    protected void startUp()
    {
        Arrays.fill(lastLevels, -1);
        pendingSounds.clear();
        clearPlayerKillCandidate();

        initialized = false;
        pendingReload = true;
        pendingLevelInit = false;
        wasDead = false;
        streamerMessageShown = false;
    }

    @Override
    protected void shutDown()
    {
        trackedItemIds.clear();
        pendingSounds.clear();
        clearPlayerKillCandidate();

        initialized = false;
        pendingReload = true;
        pendingLevelInit = false;
        wasDead = false;
        streamerMessageShown = false;
    }

    private void reloadConfig()
    {
        trackedItemIds.clear();

        String raw = config.trackedItems();

        if (raw == null || raw.trim().isEmpty())
        {
            return;
        }

        for (String name : raw.split(","))
        {
            String trimmed = name.trim();

            if (trimmed.isEmpty())
            {
                continue;
            }

            int id = findItemIdByName(trimmed);

            if (id != -1)
            {
                trackedItemIds.add(id);
            }
        }
    }

    private int findItemIdByName(String itemName)
    {
        return itemManager.search(itemName).stream()
                .filter(item -> item.getName().equalsIgnoreCase(itemName))
                .mapToInt(ItemPrice::getId)
                .findFirst()
                .orElse(-1);
    }

    @Subscribe
    public void onConfigChanged(ConfigChanged event)
    {
        if (!"boomsepicsounds".equals(event.getGroup()))
        {
            return;
        }

        if ("enableStreamerMessage".equals(event.getKey()))
        {
            streamerMessageShown = false;
            sendStreamerMessage();
            return;
        }

        pendingReload = true;
    }

    @Subscribe
    public void onLootReceived(LootReceived event)
    {
        if (!config.enableItemSounds() || event.getItems() == null)
        {
            return;
        }

        for (ItemStack item : event.getItems())
        {
            if (item == null || item.getId() <= 0)
            {
                continue;
            }

            boolean trackedMatch =
                    trackedItemIds.contains(item.getId());

            int price = itemManager.getItemPrice(item.getId());

            long stackValue =
                    (long) price * item.getQuantity();

            boolean valueMatch =
                    stackValue >= config.minimumLootValue();

            boolean shouldTrigger =
                    (config.lootSoundMode()
                            == BoomsEpicSoundsConfig.LootSoundMode.TRACKED_ITEMS
                            && trackedMatch)
                            || (config.lootSoundMode()
                            == BoomsEpicSoundsConfig.LootSoundMode.GP_VALUE
                            && valueMatch)
                            || (config.lootSoundMode()
                            == BoomsEpicSoundsConfig.LootSoundMode.BOTH
                            && (trackedMatch || valueMatch));

            if (shouldTrigger)
            {
                trigger(SoundEvent.LOOT);
                return;
            }
        }
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged event)
    {
        if (event.getGameState() == GameState.LOGGED_IN)
        {
            if (lastLevels[0] == -1)
            {
                pendingLevelInit = true;
            }

            if (!streamerMessageShown)
            {
                sendStreamerMessage();
            }
        }
        else if (event.getGameState() == GameState.LOGIN_SCREEN)
        {
            streamerMessageShown = false;
            pendingLevelInit = false;

            Arrays.fill(lastLevels, -1);
            clearPlayerKillCandidate();
        }
    }

    @Subscribe
    public void onStatChanged(StatChanged event)
    {
        if (!config.levelUps())
        {
            return;
        }

        Skill skill = event.getSkill();
        int index = skill.ordinal();
        int currentLevel = event.getLevel();

        if (lastLevels[index] == -1)
        {
            lastLevels[index] = currentLevel;
            return;
        }

        if (currentLevel > lastLevels[index])
        {
            trigger(SoundEvent.LEVEL_UP);
        }

        lastLevels[index] = currentLevel;
    }

    /*
     * Records a PvP death candidate.
     *
     * This does not play the sound by itself. The game must also send a
     * matching "You have defeated <name>" message shortly afterwards.
     */
    @Subscribe
    public void onActorDeath(ActorDeath event)
    {
        Actor actor = event.getActor();

        if (!(actor instanceof Player))
        {
            return;
        }

        Player deadPlayer = (Player) actor;
        Player localPlayer = client.getLocalPlayer();

        if (localPlayer == null || deadPlayer == localPlayer)
        {
            return;
        }

        /*
         * Confirm that the local player and dead player were interacting.
         *
         * Either direction is accepted because one actor's interacting
         * reference may clear slightly before the death event is received.
         */
        boolean localWasTargetingDeadPlayer =
                localPlayer.getInteracting() == deadPlayer;

        boolean deadPlayerWasTargetingLocal =
                deadPlayer.getInteracting() == localPlayer;

        if (!localWasTargetingDeadPlayer && !deadPlayerWasTargetingLocal)
        {
            return;
        }

        String deadPlayerName = deadPlayer.getName();

        if (deadPlayerName == null || deadPlayerName.trim().isEmpty())
        {
            return;
        }

        recentlyDefeatedPlayerName =
                Text.standardize(deadPlayerName)
                        .toLowerCase(Locale.ROOT);

        recentlyDefeatedPlayerTick = client.getTickCount();

        log.debug(
                "Recorded PvP death candidate: {} at tick {}",
                recentlyDefeatedPlayerName,
                recentlyDefeatedPlayerTick
        );
    }

    @Subscribe
    public void onGameTick(GameTick event)
    {
        if (!initialized || pendingReload)
        {
            reloadConfig();
            initialized = true;
            pendingReload = false;
        }

        if (pendingLevelInit)
        {
            initialiseLevels();
            pendingLevelInit = false;
        }

        /*
         * Remove an unconfirmed PvP candidate once its time window expires.
         */
        if (recentlyDefeatedPlayerName != null
                && client.getTickCount() - recentlyDefeatedPlayerTick
                > PLAYER_KILL_CONFIRMATION_TICKS)
        {
            clearPlayerKillCandidate();
        }

        if (tradeManager.check())
        {
            trigger(SoundEvent.TRADE_ACCEPTED);
        }

        Player player = client.getLocalPlayer();

        if (player != null)
        {
            boolean dead = player.getHealthRatio() == 0;

            if (dead && !wasDead && config.death())
            {
                trigger(SoundEvent.DEATH);
            }

            wasDead = dead;

            if (livestreamManager.check(client.getTickCount()))
            {
                trigger(SoundEvent.LIVESTREAM);
            }
        }

        playNextQueuedSound();
    }

    @Subscribe
    public void onChatMessage(ChatMessage event)
    {
        String message = event.getMessage();

        if (message == null)
        {
            return;
        }

        String standardizedMessage =
                Text.standardize(message)
                        .toLowerCase(Locale.ROOT);

        /*
         * Abuse report confirmations use SNAPSHOTFEEDBACK.
         */
        if (event.getType() == ChatMessageType.SNAPSHOTFEEDBACK)
        {
            if (config.sendReport()
                    && standardizedMessage.contains("abuse report"))
            {
                trigger(SoundEvent.REPORT);
            }

            return;
        }

        /*
         * Block private messages, public chat, clan chat and friends chat.
         */
        if (event.getType() != ChatMessageType.GAMEMESSAGE
                && event.getType() != ChatMessageType.SPAM)
        {
            return;
        }

        /*
         * Confirm that the recently dead Player is the exact player named
         * by the game's "You have defeated..." message.
         */
        if (config.playerKilling()
                && recentlyDefeatedPlayerName != null
                && recentlyDefeatedPlayerTick >= 0)
        {
            int ticksSinceDeath =
                    client.getTickCount() - recentlyDefeatedPlayerTick;

            boolean withinConfirmationWindow =
                    ticksSinceDeath >= 0
                            && ticksSinceDeath
                            <= PLAYER_KILL_CONFIRMATION_TICKS;

            boolean defeatedMessage =
                    standardizedMessage.contains("you have defeated");

            boolean matchingPlayerName =
                    standardizedMessage.contains(
                            recentlyDefeatedPlayerName
                    );

            if (withinConfirmationWindow
                    && defeatedMessage
                    && matchingPlayerName)
            {
                trigger(SoundEvent.PLAYER_KILL);
                clearPlayerKillCandidate();
                return;
            }
        }

        for (ChatTrigger chatTrigger : chatTriggers)
        {
            if (chatTrigger.matches(standardizedMessage, config))
            {
                trigger(chatTrigger.getEvent());
                return;
            }
        }
    }

    private void clearPlayerKillCandidate()
    {
        recentlyDefeatedPlayerName = null;
        recentlyDefeatedPlayerTick = -1;
    }

    private void trigger(SoundEvent event)
    {
        if (!pendingSounds.contains(event))
        {
            pendingSounds.add(event);
        }
    }

    private void playNextQueuedSound()
    {
        if (pendingSounds.isEmpty())
        {
            return;
        }

        SoundEvent next = pendingSounds.poll();

        soundManager.play(
                next,
                config.announcementVolume()
        );

        /*
         * Only the highest-priority event from this tick is played.
         */
        pendingSounds.clear();
    }

    private void sendStreamerMessage()
    {
        if (!config.enableStreamerMessage())
        {
            return;
        }

        chatMessageManager.queue(
                QueuedMessage.builder()
                        .type(ChatMessageType.GAMEMESSAGE)
                        .runeLiteFormattedMessage(
                                "<col=ff0000>"
                                        + STREAMER_MESSAGE
                                        + "</col>"
                        )
                        .build()
        );

        streamerMessageShown = true;
    }

    private void initialiseLevels()
    {
        for (Skill skill : Skill.values())
        {
            lastLevels[skill.ordinal()] =
                    client.getRealSkillLevel(skill);
        }
    }
}

package com.thearkane.boomsepicsounds;

import lombok.Getter;

import java.util.function.Predicate;

/**
 * Pairs a set of chat phrases + a config toggle with the SoundEvent to fire.
 * Instead of a growing if/else chain in onChatMessage, the plugin just loops
 * over a List<ChatTrigger> - adding a new chat-based sound is one new entry.
 */

public class ChatTrigger
{
    @Getter
    private final SoundEvent event;
    private final Predicate<BoomsEpicSoundsConfig> enabledCheck;
    private final String[] phrases;

    public ChatTrigger(SoundEvent event, Predicate<BoomsEpicSoundsConfig> enabledCheck, String... phrases)
    {
        this.event = event;
        this.enabledCheck = enabledCheck;
        this.phrases = phrases;
    }

    public boolean matches(String lowerCaseMessage, BoomsEpicSoundsConfig config)
    {
        if (!enabledCheck.test(config))
        {
            return false;
        }

        for (String phrase : phrases)
        {
            if (lowerCaseMessage.contains(phrase))
            {
                return true;
            }
        }

        return false;
    }
}

package com.thearkane.boomsepicsounds;

import java.io.File;
import java.util.EnumMap;
import java.util.Map;
import java.util.Random;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.RuneLite;
import net.runelite.client.audio.AudioPlayer;

/**
 * Owns everything to do with where sound files live and how they get played.
 * The plugin class no longer needs to know about File, folders, or gain math.
 */

@Slf4j
@Singleton

public class SoundManager
{
    private static final String ROOT_FOLDER = "booms-epic-sounds";
    private static final long CACHE_TTL_MS = 5_000;

    private final AudioPlayer audioPlayer;
    private final File soundsDirectory;
    private final Random random = new Random();

    // Cache directory listings instead of hitting disk on every trigger.
    private final Map<SoundEvent, File[]> cachedFiles = new EnumMap<>(SoundEvent.class);
    private final Map<SoundEvent, Long> cacheTimestamps = new EnumMap<>(SoundEvent.class);

    @Inject
    public SoundManager(AudioPlayer audioPlayer)
    {
        this.audioPlayer = audioPlayer;
        this.soundsDirectory = new File(RuneLite.RUNELITE_DIR, ROOT_FOLDER);

        for (SoundEvent event : SoundEvent.values())
        {
            createFolder(event.getFolderName());
        }
    }

    private void createFolder(String name)
    {
        File folder = new File(soundsDirectory, name);
        if (!folder.exists() && !folder.mkdirs())
        {
            log.debug("Unable to create sound folder: {}", folder.getAbsolutePath());
        }
    }

    /**
     * Plays a custom sound for this event if the user has dropped .wav files
     * into its folder, otherwise falls back to the bundled sound(s).
     */
    public void play(SoundEvent event, int volumePercent)
    {
        int volume = Math.max(0, Math.min(100, volumePercent));
        if (volume == 0)
        {
            return;
        }

        float gain = (float) (20.0 * Math.log10(volume / 100.0));

        File custom = getRandomCustomSound(event);
        if (custom != null)
        {
            playLocal(custom, gain);
            return;
        }

        String[] fallback = event.getFallbackSounds();
        if (fallback.length == 0)
        {
            return;
        }

        playResource(fallback[random.nextInt(fallback.length)], gain);
    }

    /** Call this (e.g. from a config-changed listener) if you want to force a re-scan. */
    public void invalidateCache(SoundEvent event)
    {
        cachedFiles.remove(event);
        cacheTimestamps.remove(event);
    }

    private File getRandomCustomSound(SoundEvent event)
    {
        File[] files = getCachedFiles(event);
        if (files == null || files.length == 0)
        {
            return null;
        }
        return files[random.nextInt(files.length)];
    }

    private File[] getCachedFiles(SoundEvent event)
    {
        long now = System.currentTimeMillis();
        Long timestamp = cacheTimestamps.get(event);

        if (timestamp != null && now - timestamp < CACHE_TTL_MS)
        {
            return cachedFiles.get(event);
        }

        File folder = new File(soundsDirectory, event.getFolderName());
        File[] files = folder.listFiles((dir, name) -> name.toLowerCase().endsWith(".wav"));

        cachedFiles.put(event, files);
        cacheTimestamps.put(event, now);

        return files;
    }

    private void playLocal(File file, float gain)
    {
        try
        {
            audioPlayer.play(file, gain);
        }
        catch (Exception e)
        {
            log.debug("Unable to play local sound {}", file.getAbsolutePath(), e);
        }
    }

    private void playResource(String soundFile, float gain)
    {
        try
        {
            audioPlayer.play(BoomsEpicSoundsPlugin.class, soundFile, gain);
        }
        catch (Exception e)
        {
            log.debug("Unable to play bundled sound {}", soundFile, e);
        }
    }
}

package com.thearkane.boomsepicsounds;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;

@ConfigGroup("boomsepicsounds")
public interface BoomsEpicSoundsConfig extends Config
{
    enum LootSoundMode
    {
        TRACKED_ITEMS,
        GP_VALUE,
        BOTH
    }

    // =====================================================
    // SECTIONS
    // =====================================================

    @ConfigSection(
            name = "General",
            description = "General plugin settings",
            position = 0
    )
    String generalSection = "general";

    @ConfigSection(
            name = "Chat",
            description = "Chat message notifications",
            position = 1
    )
    String chatSection = "chat";

    @ConfigSection(
            name = "Loot",
            description = "Loot drop settings",
            position = 2
    )
    String lootSection = "loot";

    @ConfigSection(
            name = "Combat & Specials",
            description = "Weapon special attacks and combat triggers",
            position = 3
    )
    String combatSection = "combat";

    @ConfigSection(
            name = "PvP",
            description = "Player vs Player triggers",
            position = 4
    )
    String pvpSection = "pvp";

    @ConfigSection(
            name = "Achievements",
            description = "Level ups, quests, pets, diaries and progression triggers",
            position = 5
    )
    String achievementSection = "achievements";

    @ConfigSection(
            name = "Misc",
            description = "Misc triggers",
            position = 6
    )
    String miscSection = "misc";

    // =====================================================
    // GENERAL
    // =====================================================

    @ConfigItem(
            keyName = "announcementVolume",
            name = "Announcement Volume",
            description = "Controls overall sound volume",
            section = generalSection,
            position = 0
    )
    default int announcementVolume() { return 100; }

    // =====================================================
    // CHAT
    // =====================================================

    @ConfigItem(
            keyName = "enableStreamerMessage",
            name = "Enable Streamer Message",
            description = "Shows a local chatbox message for BoomEpicKill",
            section = chatSection,
            position = 0
    )
    default boolean enableStreamerMessage() { return true; }

    @ConfigItem(
            keyName = "livestreamChatNotification",
            name = "Livestream Chat Notification",
            description = "Display a local chat message when BoomEpicKill goes live",
            section = chatSection
    )
    default boolean livestreamChatNotification()
    {
        return true;
    }

    @ConfigItem(
            keyName = "livestreamSoundNotification",
            name = "Livestream Sound Notification",
            description = "Play a sound when BoomEpicKill goes live",
            section = chatSection
    )
    default boolean livestreamSoundNotification()
    {
        return true;
    }

    // =====================================================
    // LOOT
    // =====================================================

    @ConfigItem(
            keyName = "enableItemSounds",
            name = "Enable Item Sounds",
            description = "Master toggle for loot sound notifications",
            section = lootSection,
            position = 0
    )
    default boolean enableItemSounds()
    {
        return true;
    }

    @ConfigItem(
            keyName = "lootSoundMode",
            name = "Loot Trigger Mode",
            description = "Choose whether sounds trigger from tracked items, GP value, or both",
            section = lootSection,
            position = 1
    )
    default LootSoundMode lootSoundMode()
    {
        return LootSoundMode.GP_VALUE;
    }

    @ConfigItem(
            keyName = "minimumLootValue",
            name = "Minimum GP Value",
            description = "Plays sound when a loot item stack is worth at least this much GP",
            section = lootSection,
            position = 2
    )
    default int minimumLootValue()
    {
        return 100000;
    }

    @ConfigItem(
            keyName = "trackedItems",
            name = "Tracked Items",
            description = "Comma separated item names",
            section = lootSection,
